#include "pico/stdlib.h"
#include "hardware/clocks.h"
#include "hardware/vreg.h"

#include "hw_config.h"
#include "display.h"
#include "input.h"
#include "menu.h"
#include "cart_ram.h"

#include "audio.h"
#include "timing.h"

// Peanut-GB — single-header Game Boy emulator
#include "peanut_gb.h"

// ROM compiled into flash (generated by tools/convert_rom.py)
#define ROM_DATA_IMPLEMENTATION
#include "rom_data.h"

// Framebuffer: GB native resolution, native RGB565
static uint16_t framebuf[GB_LCD_WIDTH * GB_LCD_HEIGHT];

// Grayscale palette — native RGB565 (byte order handled by display driver)
static const uint16_t palette[4] = {
    0xFFFF,  // White (lightest)
    0xAD55,  // Light gray
    0x528A,  // Dark gray
    0x0000,  // Black (darkest)
};

// --- Peanut-GB callbacks ---

static int current_rom = 0;

uint8_t gb_rom_read(struct gb_s *gb, const uint_fast32_t addr) {
    (void)gb;
    if (addr >= rom_list[current_rom].size)
        return 0xFF;
    return rom_list[current_rom].data[addr];
}

void gb_error(struct gb_s *gb, const enum gb_error_e err, const uint16_t addr) {
    (void)gb;
    (void)err;
    (void)addr;
}

void lcd_draw_line(struct gb_s *gb, const uint8_t *pixels, const uint_fast8_t line) {
    (void)gb;
    uint16_t *dst = &framebuf[line * GB_LCD_WIDTH];
    for (int x = 0; x < GB_LCD_WIDTH; x++) {
        uint8_t shade = pixels[x] & 0x03;
        dst[x] = palette[shade];
    }
}

// --- Emulator init ---

static struct gb_s gb;

static void emu_init(void) {
    audio_reset();
    // Disable old cartridge RAM while initializing the new core context.
    cart_ram_init(0);

    enum gb_init_error_e err = gb_init(&gb,
        gb_rom_read, gb_cart_ram_read, gb_cart_ram_write,
        gb_error, NULL);

    size_t ram_size = 0;
    if (err != GB_INIT_NO_ERROR ||
        gb_get_save_size_s(&gb, &ram_size) != 0 ||
        !cart_ram_init(ram_size)) {
        display_fill(0xF800);
        while (1) tight_loop_contents();
    }

    gb_init_lcd(&gb, lcd_draw_line);
}

// --- Main ---

int main(void) {
    vreg_set_voltage(VREG_VOLTAGE_1_20);
    sleep_ms(10);
    set_sys_clock_khz(250000, true);

    stdio_init_all();
    display_init();
    input_init();
    audio_init();

    // Show menu on startup if multiple ROMs available
    if (ROM_COUNT > 1) {
        current_rom = menu_select_game(framebuf, ROM_COUNT, 0);
    }

    emu_init();

    frame_clock_t frame_clock;
    frame_clock_reset(&frame_clock, time_us_64());

    // Main emulation loop
    while (1) {
        joypad_t jp = input_read();

        // Reserve Start+Select for the menu; ordinary Select reaches the game.
        if (ROM_COUNT > 1 && input_menu_requested(jp)) {
            audio_pause();
            int choice = menu_select_game(framebuf, ROM_COUNT, current_rom);
            if (choice != current_rom) {
                current_rom = choice;
                emu_init();
            }
            // Re-read joypad after menu exits
            jp = input_read();
            frame_clock_reset(&frame_clock, time_us_64());
        }

        gb.direct.joypad = jp.byte;

        gb_run_frame(&gb);

        display_frame(framebuf);
        audio_play_frame();
        sleep_until(from_us_since_boot(frame_clock_next(&frame_clock, time_us_64())));
    }
}
